#!/usr/bin/env python3
"""Instalador Vera v2: migracion + API."""
import os, base64, shutil, subprocess
from datetime import datetime

VELA = os.path.expanduser('~/Desktop/vela/backend')
API_DIR = os.path.join(VELA, 'api')
MAIN_PY = os.path.join(VELA, 'main.py')

if not os.path.exists(VELA):
    print("ERROR: backend no encontrado"); exit(1)

print("Paso 1: ejecutar migracion SQL...")
mig_path = os.path.join(VELA, 'migration_vera_v2.py')
with open(mig_path, 'wb') as f:
    f.write(base64.b64decode(""))
r = subprocess.run(['python3', mig_path], capture_output=True, text=True, cwd=VELA)
print(r.stdout)
if r.returncode != 0:
    print("ERROR migracion:", r.stderr); exit(1)

print("\nPaso 2: copiar API...")
api_path = os.path.join(API_DIR, 'vera_v2.py')
if os.path.exists(api_path):
    backup = os.path.join(API_DIR, f'vera_v2.py.backup_{datetime.now().strftime("%H%M%S")}')
    shutil.copy(api_path, backup)
    print(f"  ~ backup: {backup}")
with open(api_path, 'wb') as f:
    f.write(base64.b64decode(""))
print(f"  + {api_path}")

print("\nPaso 3: registrar en main.py...")
with open(MAIN_PY) as f: content = f.read()
shutil.copy(MAIN_PY, MAIN_PY + '.bak_v2_' + datetime.now().strftime("%H%M%S"))

if 'from api.vera_v2 import router' not in content:
    lines = content.split('\n')
    idx = 0
    for i, l in enumerate(lines):
        if l.startswith('from api.') or l.startswith('from vera.'):
            idx = i + 1
    lines.insert(idx, 'from api.vera_v2 import router as vera_v2_router')
    content = '\n'.join(lines)
    print("  + import anadido")

if 'vera_v2_router' not in content.split('app.include_router')[-1]:
    lines = content.split('\n')
    last = 0
    for i, l in enumerate(lines):
        if 'app.include_router' in l: last = i
    lines.insert(last + 1, 'app.include_router(vera_v2_router)')
    content = '\n'.join(lines)
    print("  + include_router anadido")

with open(MAIN_PY, 'w') as f: f.write(content)

print("\nOK Instalacion completa")
print("\nReinicia uvicorn y prueba:")
print('  curl -s "http://localhost:8000/api/vera/v2/status" -H "Authorization: Bearer $TOKEN" | python3 -m json.tool')
